"""Tripo Studio image-page prompts (GPT Image 2.5) for the ch3 v2 concept sheets. Writes prompts/<ID>.txt"""
from pathlib import Path

HEAD = ("MANDATORY: ONE SINGLE HORIZONTAL ROW of exactly four separate orthographic views of the SAME object, left to right: "
        "1 FRONT view; 2 LEFT side view (object turned so its front points to the LEFT edge of the image); 3 BACK view; "
        "4 RIGHT side view (object turned so its front points to the RIGHT edge of the image). Same scale and same ground line "
        "in all four, wide empty gaps between the views, every view complete and not cropped. Plain flat light neutral grey "
        "background (#D6D6D6). No floor, no ground shadow, no text, no labels, no frames, no perspective, no extra objects. "
        "No fire, no smoke, no sparks, no lava stream, no lava pool, no glow halo: hot cracks and furnace interiors are painted "
        "only as flat opaque bright orange-yellow colour areas.\n\n"
        "STYLE: stylized hand-painted 3D game environment asset in the readable style of Gunfire Reborn: bold chunky silhouette, "
        "broad clean faceted planes, two or three dominant colour blocks (dark charcoal basalt, black iron with big rivets, deep "
        "vermilion lacquer, warm dark bronze), soft painted gradients, sparse wear, soot-darkened edges. No photorealism, no "
        "micro-grain, no dense tiny cracks, no tiny carvings, no harsh highlights.\n\n")

P = {
"SM_Tripo_InfernoHangingForge": (26, 8, 26, """A huge square iron forge platform hanging in the air, a wide FLAT walkable arena deck, the same from all four sides. From bottom to top: (1) under the deck a shallow round upside-down black iron bowl (furnace belly) 2m deep and 16m across, ringed by eight small round ports painted flat bright orange; (2) the deck: one thick square slab of riveted black iron plates 1.5m thick, its edge faces trimmed with a deep vermilion lacquered band; its top is a big FLAT EMPTY floor of dark iron plates; (3) a very low black iron kerb 0.6m tall along the deck edges with one 4m gap in the middle of each side; (4) at each of the four corners a separate squat thick square black iron pillar 4.5m tall with a flat top and one big iron ring on its outer side; (5) in the exact centre a square basalt step base 7m wide and 1.4m tall carrying a squat round black iron furnace 3.5m wide and 3m tall whose open top is a flat bright orange coal bed. Nothing else on the deck. PROPORTIONS: every view about 3.2 times as wide as tall: a wide thin slab, a shallow bowl under it, four short corner posts and one central furnace. NO chains anywhere (not between the posts, not hanging), no railings, no anvils, no spikes."""),
"SM_Tripo_InfernoGatehouse": (16, 12, 14, """A massive fortified gate BLOCK of dark charcoal basalt (like a short thick section of a city wall), NOT a tower and NOT a hall: a solid stone block 12m wide, 8m tall and 14m deep with a FLAT ROOF TERRACE on top. One big rectangular gate passage 8m wide and 6m tall goes straight through the block from FRONT to BACK; the passage is EMPTY and open (no gate, no door) with a flat black iron lintel and a narrow vertical slot groove in each side wall. Heavy black iron corner plates with big rivets on the vertical edges; a big cast bronze plaque with a raised sun emblem above the passage on the FRONT face; a short deep vermilion lacquered timber pent eave with dark tiles above the passage on the FRONT and BACK faces at two thirds of the height. The FLAT ROOF TERRACE is open and walkable, surrounded by a solid basalt parapet 1.1m tall with square merlons; on it there is NO building, NO roof and NO hall, only two tiny square watch kiosks 3m wide with vermilion posts and small dark pyramid roofs at the two BACK corners, reaching 12m. On the LEFT and RIGHT outer side walls one straight external stone stair climbs diagonally from the ground at the front corner up to the roof terrace at the back. PROPORTIONS: FRONT and BACK views about 1.33 times as wide as tall: a wide low stone block with the open passage and the two small kiosks on top; LEFT and RIGHT views about 1.17 times as wide as tall showing the diagonal side stair. Big broad blocks, no fine brick seams, no flags, no banners."""),
"SM_Tripo_InfernoBasaltColumns": (8, 9, 7, """A cluster of six thick fused hexagonal basalt columns rising from the ground, used as cover and stepping stones. Each column is a chunky six-sided prism about 2m across with a FLAT hexagonal top. The columns step up like a staircase with clearly different heights: 3m, 4.5m, 6m, 7m, 8m and 9m; the two lowest stand at the FRONT-LEFT, the tallest at the BACK-RIGHT. Dark charcoal basalt with soot-darkened edges and slightly lighter worn flat tops; one wide crack around the shared foot painted as a flat bright orange band. Irregular asymmetric outline from every side. PROPORTIONS: FRONT and BACK views about 0.9 times as wide as tall; LEFT and RIGHT views about 0.8 times as wide as tall."""),
"SM_Tripo_InfernoScaffold": (12, 10, 8, """A sturdy two-level work scaffold built against a rock wall, made of thick black iron posts and girders with big rivets and heavy charred dark timber beams and planks. LOWER LEVEL: a FLAT plank deck 4.5m above the ground covering the LEFT half. UPPER LEVEL: a FLAT plank deck 9m above the ground covering the whole width at the top. One straight wide black iron ramp with cleats, 3m wide, climbs at a gentle slope across the FRONT face from the lower deck on the LEFT up to the upper deck at the RIGHT. Both decks have a simple black iron railing 1.1m tall on their open edges with vermilion lacquered post caps. The BACK of the scaffold is a FLAT vertical face with no railing (it is set against the rock wall). Thick chunky members only, every post at least 0.5m thick. PROPORTIONS: FRONT and BACK views about 1.2 times as wide as tall; LEFT and RIGHT views about 0.8 times as wide as tall."""),
"SM_Tripo_InfernoIronBridge": (12, 2.5, 10, """A short heavy black iron bridge span, 12m long from LEFT to RIGHT and 10m wide from FRONT to BACK. The bridge body is a thick black iron box girder 0.8m deep covered with riveted plates; its top is a wide FLAT walkable deck of iron plates. Along the FRONT edge and the BACK edge runs a solid black iron railing 1.1m tall with thick square posts and riveted panels; the FRONT railing has one 3m wide gap in its middle, the BACK railing is continuous. At the four corners stand four squat cast bronze posts 1.7m tall, each topped with a chunky roaring beast head facing outward along the bridge. A few vermilion lacquered iron strips on the deck. PROPORTIONS: FRONT and BACK views about 4.8 times as wide as tall, a long low flat span; LEFT and RIGHT views about 4 times as wide as tall. No arches under the deck, no water, no lava."""),
"SM_Tripo_InfernoHallTruss": (24, 9, 8, """One giant roof truss of a ruined blast hall, shown on its own. A gabled A-shaped frame: a thick straight horizontal tie beam 24m long at the bottom, two thick rafters rising from its ends to a ridge point at 9m, a short king post and two diagonal struts inside the triangle; heavy charred dark timber members 0.8m thick clad with black iron straps and big rivets. At both ends the tie beam rests on a chunky stepped bracket set (dougong) of vermilion lacquered wood blocks 2m tall. Five thick timber purlins 8m long run front to back across the rafters; on the LEFT half of the roof a sheet of dark grey roof tiles hangs on the purlins with a ragged broken edge, the RIGHT half shows bare purlins. PROPORTIONS: FRONT and BACK views about 2.7 times as wide as tall showing the full triangle; LEFT and RIGHT views about 0.9 times as wide as tall showing the purlins end on. Thick members only, no thin sticks."""),
"SM_Tripo_InfernoLadleCrane": (18, 16, 8, """A giant gantry crane frame of a mythic foundry, massive black iron with big rivets, WITHOUT any hooks, chains, ropes, winches or ladles. Two thick legs stand at the LEFT and RIGHT ends; seen from the side each leg is an A-frame of two heavy iron columns spreading to 8m at the foot. A massive horizontal box girder spans between the legs; its top at 12m is a FLAT walkable iron walkway 3m wide with a 1.1m iron railing on both long edges, reached by a straight iron ladder cage on the outside of the RIGHT leg. Above the walkway each leg ends in a squat iron pulley head with one big pulley wheel, reaching 16m. Under the girder only two plain square iron mounting brackets (nothing hangs from them). Deep vermilion lacquered bands on the girder and a few cast bronze sun discs on the legs. PROPORTIONS: FRONT and BACK views about 1.1 times as wide as tall showing the full gantry; LEFT and RIGHT views about 0.5 times as wide as tall showing one A-frame leg."""),
"SM_Tripo_InfernoCraneHook": (4, 6, 3, """A crane hook kit of two SEPARATE parts floating one above the other with a clear empty gap of 1.5m between them (no chain, no rope between them): TOP PART: a heavy black iron drum winch 4m wide and 1.6m tall, a thick horizontal drum with riveted end flanges and a squat iron bracket housing with a flat top (it bolts under a crane girder); BOTTOM PART: a big black iron crane hook block 2.6m tall, a chunky rectangular sheave block with a vermilion lacquered band and one massive curved iron hook below it, the hook thick and blunt. PROPORTIONS: every view about 0.67 times as wide as tall; FRONT and BACK views look the same, LEFT and RIGHT views show the drum end on and the hook in profile."""),
"SM_Tripo_InfernoKilnMouth": (16, 12, 5, """The monumental entrance of a forge cave cut into a basalt cliff. A thick frame of dark charcoal basalt blocks surrounds one big round-topped archway 8m wide and 7m tall that goes straight through from FRONT to BACK and is EMPTY and open; the arch is framed by a massive cast bronze beast face whose brow and fangs form the top of the arch and whose paws form the two jambs. Two huge black iron door leaves covered with rows of big round studs stand swung fully open, folded flat against the FRONT face on each side of the arch. A deep vermilion lacquered lintel band with a row of bronze discs above the arch. The inner walls of the arch are plain basalt with a few flat bright orange painted cracks; no braziers, no fire. The BACK is a FLAT rough rock face with the arch opening in it. PROPORTIONS: FRONT and BACK views about 1.33 times as wide as tall; LEFT and RIGHT views about 0.42 times as wide as tall."""),
"SM_Tripo_InfernoSpout": (5, 4, 6, """A colossal cast bronze beast-head spout mounted on a wall. A heavy square black iron back plate with rivets forms the FLAT BACK. From it the chunky warm aged bronze head of a roaring mythic beast juts forward toward the FRONT: heavy brows, curled horns lying back flat, big round eyes and a wide open mouth. Its long lower jaw is a broad EMPTY open trough reaching far forward, its inside dark crusted bronze with a thin flat bright orange painted line along the bottom; nothing flows out of it. Patches of dark verdigris and soot. PROPORTIONS: FRONT view about 1.25 times as wide as tall showing the open mouth head on; LEFT and RIGHT views about 1.5 times as wide as tall showing the long jutting jaw trough."""),
"SM_Tripo_InfernoGuardianStatue": (3.5, 7.5, 3.5, """A colossal bronze guardian statue of a fire god's warrior standing on a plinth. PLINTH: a solid square block of dark charcoal basalt 3.5m wide and 2.6m tall with a black iron top band. STATUE: a stiff, frontal, stocky armoured warrior 4.9m tall facing the FRONT, cast in warm aged bronze with patches of dark verdigris green; chunky overlapping armour plates lacquered deep vermilion on the chest and shoulders; a stern square face; a helmet with a FLAT square top; both hands hold the long haft of a big crescent-bladed yue battle axe planted upright on the plinth in front of the body, the blade beside the head. Arms close to the body, nothing sticks out beyond the plinth. PROPORTIONS: all four views about 0.47 times as wide as tall. Chunky simplified toy-like forms, no fine engraving."""),
"SM_Tripo_InfernoCausewayBreak": (12, 5, 12, """The broken end of a massive basalt causeway. A FLAT walkable top paved with big dark charcoal basalt slabs and a low kerb of square black iron-capped stones along both long edges; the two long sides are steep walls of chunky hexagonal basalt columns with a few thick black iron tie plates. The LEFT end is a clean flat cut face showing the column cross-section. Toward the RIGHT end the causeway is shattered: the last third of the top breaks off in a jagged stepped edge of snapped column stumps and big tilted slabs sliding down, with a few wide cracks in the stumps painted flat bright orange. PROPORTIONS: FRONT and BACK views about 2.4 times as wide as tall, flat on the left and broken down on the right; the LEFT view shows the clean end face, the RIGHT view the jagged broken end. No lava around it, chunky broken blocks, no small rubble."""),
"SM_Tripo_InfernoGeyserVent": (6, 2.5, 6, """A low volcanic vent cone, two clearly distinct parts: BASE: a squat round mound of chunky dark charcoal basalt plates rising to a broad crater rim; CAP: inside the rim sits a separate domed crust of cooled black lava, split by four wide cracks painted flat bright orange, with a clean flat bright orange seam ring where the crust meets the rim. Round and the same from every side. PROPORTIONS: all four views about 2.4 times as wide as tall and identical. Broad faceted chunks, no spray."""),
"SM_Tripo_InfernoWorkShed": (10, 7, 8, """A half-open foundry work shed. A flat basalt floor slab; four thick black iron corner posts with rivets and deep vermilion lacquered timber beams; a single-pitch roof of dark grey tiles sloping down from the FRONT (7m) to the BACK (5m), the LEFT part of the roof broken away to bare black rafters. The BACK wall is solid riveted black iron plates; the LEFT and RIGHT sides are closed only up to 2m by low timber plank walls; the FRONT is completely open. Under the roof on the back wall hang big chunky smith tongs, hammers and one short thick chain, and a squat iron workbench with a small anvil stands against the back wall. PROPORTIONS: FRONT and BACK views about 1.43 times as wide as tall; LEFT and RIGHT views about 1.15 times as wide as tall showing the sloping roof."""),
}

GRID_HEAD = HEAD.replace("MANDATORY: ONE SINGLE HORIZONTAL ROW of exactly four separate orthographic views of the SAME object, left to right: "
    "1 FRONT view; 2 LEFT side view (object turned so its front points to the LEFT edge of the image); 3 BACK view; "
    "4 RIGHT side view (object turned so its front points to the RIGHT edge of the image). Same scale and same ground line "
    "in all four, wide empty gaps between the views",
    "MANDATORY: a 2 by 2 GRID of exactly four separate orthographic views of the SAME object: TOP-LEFT = FRONT view; "
    "TOP-RIGHT = LEFT side view (object turned so its front points to the LEFT edge of the image); BOTTOM-LEFT = BACK view; "
    "BOTTOM-RIGHT = RIGHT side view (object turned so its front points to the RIGHT edge of the image). Each view seen "
    "straight on from slightly above (about 15 degrees) so the top surface is just visible, same scale in all four, wide empty "
    "gaps between the views")
assert GRID_HEAD != HEAD
GRID = {"SM_Tripo_InfernoHangingForge", "SM_Tripo_InfernoIronBridge", "SM_Tripo_InfernoHallTruss",
        "SM_Tripo_InfernoCausewayBreak", "SM_Tripo_InfernoGeyserVent"}

out = Path(__file__).parent / "prompts"
out.mkdir(exist_ok=True)
for aid, (w, h, d, brief) in P.items():
    txt = (GRID_HEAD if aid in GRID else HEAD) + f"OBJECT ({w:g}m wide x {h:g}m tall x {d:g}m deep): " + brief
    (out / f"{aid}.txt").write_text(txt, encoding="utf-8")
    print(aid, len(txt))
